{
  "scenario_title": "Monthly clinical trial budget burn, milestone progress, and CRO vendor expenditures across four global drug development programs, 2023-2024",
  "data_context": "The Global Clinical Operations and Finance portfolio office at Aethelgard Biopharma gathered monthly expenditure and milestone execution data from 2023 through 2024 to evaluate contract research organization (CRO) vendor performance, monitor study budget burn rates against clinical milestone progression, and identify cost-per-patient variances across active clinical development pipelines.",
  "script": "dim(\"study\", [\"Study-ONC-301\", \"Study-IMM-204\", \"Study-NEU-102\", \"Study-CV-405\"], weights=[0.35, 0.25, 0.20, 0.20], group=\"trial\")\ndim(\"cro_vendor\", [\"IQVIA Bio\", \"Parexel Int\", \"Icon Clinical\", \"Fortrea\"], weights=[0.35, 0.25, 0.25, 0.15], group=\"vendor\")\ndim(\"cost_category\", [\"Site Payments\", \"CRO Management\", \"Patient Recruitment\", \"Laboratory & Bioanalytics\", \"Regulatory & Monitoring\"], weights=[0.30, 0.25, 0.20, 0.15, 0.10], group=\"cost\")\ndim(\"trial_phase_stage\", [\"Site Activation\", \"First Patient In\", \"50% Enrolled\", \"Last Patient In\", \"Database Lock\"], weights=[0.32, 0.26, 0.20, 0.14, 0.08], ordered=\"stage\", group=\"milestone\")\n\ntime(\"report_month\", start=\"2023-01-01\", end=\"2024-12-31\", freq=\"monthly\")\n\nmeasure(\"spend_thousands\", \"gamma(shape=4.0, scale=12.5) * {\\\"Site Payments\\\": 2.2, \\\"CRO Management\\\": 1.8, \\\"Patient Recruitment\\\": 1.4, \\\"Laboratory & Bioanalytics\\\": 1.1, \\\"Regulatory & Monitoring\\\": 0.7}[cost_category] * (1.0 + 0.25 * [study=Study-ONC-301] + 0.15 * [cro_vendor=IQVIA Bio])\", unit=\"USD thousands\", additive=True)\nmeasure(\"milestone_completion_pct\", \"clip(12.0 + {\\\"Site Activation\\\": 8.0, \\\"First Patient In\\\": 28.0, \\\"50% Enrolled\\\": 52.0, \\\"Last Patient In\\\": 78.0, \\\"Database Lock\\\": 96.0}[trial_phase_stage] + gaussian(0, 3.5) + (report_month / 730.0) * 4.0, 0.0, 100.0)\", unit=\"percent\", additive=False)\nmeasure(\"cost_per_patient\", \"clip((spend_thousands * 1000.0) / (10.0 + 6.0 * [study=Study-ONC-301] + 4.0 * [cost_category=Patient Recruitment] + poisson(5)), 1200.0, 35000.0)\", unit=\"USD\", additive=False)\n\nemit(750)",
  "intents": [
    {
      "sentence": "Which CRO vendors account for the highest total clinical trial spend",
      "columns": [
        "cro_vendor",
        "spend_thousands"
      ],
      "aggregate": "SUM",
      "family": "comparison"
    },
    {
      "sentence": "Track monthly budget spend trends across study programs over time",
      "columns": [
        "report_month",
        "study",
        "spend_thousands"
      ],
      "aggregate": "SUM",
      "family": "trend"
    },
    {
      "sentence": "Examine whether higher milestone completion correlates with unit cost per enrolled patient",
      "columns": [
        "milestone_completion_pct",
        "cost_per_patient"
      ],
      "aggregate": "NONE",
      "family": "relation"
    },
    {
      "sentence": "Analyze the drop-off and distribution of monthly operational records across successive trial milestone stages",
      "columns": [
        "trial_phase_stage"
      ],
      "aggregate": "COUNT",
      "family": "process"
    }
  ]
}
